package ec.espe.facturacion.application;
import ec.espe.facturacion.domain.*; import java.math.*; import java.time.Instant; import java.util.UUID;
public final class CreateInvoiceUseCase { private final InvoiceRepository repository; private final BigDecimal rate,threshold; public CreateInvoiceUseCase(InvoiceRepository r,BigDecimal t,BigDecimal h){repository=r;rate=t;threshold=h;} public Invoice execute(CreateInvoiceCommand c){if(c.operationId()==null||c.operationId().isBlank())throw new BusinessRuleException("operationId es obligatorio"); var old=repository.findByOperationId(c.operationId()); if(old.isPresent())return old.get(); if(c.customerId()==null||c.customerId().isBlank()||c.lines().isEmpty())throw new BusinessRuleException("Cliente y detalles son obligatorios"); if(c.customerId().toUpperCase().startsWith("RISK-"))throw new BusinessRuleException("Cliente rechazado por política antifraude"); var sub=c.lines().stream().map(InvoiceLine::amount).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP); var tax=sub.multiply(rate).setScale(2,RoundingMode.HALF_UP); var status=sub.compareTo(threshold)>0?"PENDING_REVIEW":"APPROVED"; var invoice=new Invoice(UUID.randomUUID(),c.operationId(),c.customerId(),sub,tax,sub.add(tax).setScale(2,RoundingMode.HALF_UP),status,Instant.now()); repository.save(invoice,c); return invoice;} }